(W/'app.js').write_text('''"use strict";
const findings={asd_kinect:"Summary SFT changes which class is predicted most often, but leaves macro-F1 unchanged. Neither view closes the gap to the supervised references.",ataxia:"Eight test clips from four participants make this a descriptive comparison. It cannot support a powered ranking or population-level claim.",care_pd:"Summary evidence outperforms shuffled evidence by 0.065 macro-F1 in the archived paired analysis. SFT improves the point estimate but remains below the linear reference.",gmfcs:"The common subject-disjoint protocol reports a summary-SFT gain from 0.265 to 0.467. It remains below matched LR (0.579). Full split inputs are required for independent provenance verification.",parkinsonism:"Named z-features outperform summaries in this setting. The result comes from 29 clips and five participants, so population uncertainty remains substantial.",pathogait:"SFT recovers substantial in-distribution signal but remains below the matched references. Only two test participants are available."};
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
fetch('data.json').then(r=>{if(!r.ok)throw Error('Could not load results');return r.json()}).then(({datasets,cases})=>{
const tabs=document.querySelector('#tabs');datasets.forEach((d,i)=>{const b=el('button',d.name);b.type='button';b.role='tab';b.setAttribute('aria-selected',i===0?'true':'false');b.onclick=()=>show(d);tabs.append(b);const card=el('div');card.append(el('b',d.name),el('small',`${d.n} clips · ${d.subjects} participants`));document.querySelector('#dataset-strip').append(card);const tr=el('tr');[d.name,d.summary,d.features,d.sft,d.lr,d.svm].forEach((v,j)=>tr.append(el(j?'td':'th',j?v.toFixed(3):v)));document.querySelector('#all-results').append(tr)});
function show(d){[...tabs.children].forEach(b=>b.setAttribute('aria-selected',String(b.textContent===d.name)));document.querySelector('#result-name').textContent=d.name;document.querySelector('#sample-size').textContent=`${d.n} clips / ${d.subjects} test participants`;const bars=document.querySelector('#bars');bars.replaceChildren();[['Summary zero-shot',d.summary],['Z-feature zero-shot',d.features],['Summary LoRA-SFT',d.sft],['Matched LR',d.lr]].forEach(([n,v])=>{const row=el('div',undefined,'barrow');const track=el('div',undefined,'bartrack');const fill=el('div',undefined,'barfill');fill.style.width=`${100*v}%`;track.append(fill);row.append(el('span',n),track,el('b',v.toFixed(3)));bars.append(row)});document.querySelector('#finding').textContent=findings[d.id];const box=document.querySelector('#cases');box.replaceChildren();cases.filter(c=>c.dataset===d.id).forEach(c=>{const row=el('div',undefined,'case');row.append(el('span',`True: ${c.true}`),el('code',c.raw_output),el('b',c.true===c.pred?'Correct':'Incorrect',c.true===c.pred?'correct':'incorrect'));box.append(row)})}show(datasets[0]);
}).catch(e=>{document.querySelector('#result-name').textContent=e.message});
''')
(W/'sources.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GaitEval source examples and attribution</title><link rel="stylesheet" href="style.css"></head><body><main><section class="section"><a href="index.html">← GaitEval</a><h1>Sources & attribution</h1><p>Examples illustrate source resources and are not paired with evaluated predictions. No image is supplied to the language models.</p><ul><li>ASD-Kinect: original recorded skeleton video, Dataset/Autism/children with ASD/1/video/Svideo.avi, frame at 0.5 seconds. <a href="https://zenodo.org/records/4025120">Al-Jubouri et al. dataset record</a>.</li><li>ATAXIA: captured-video examples from Khalil et al., Diagnosis of Cerebellar Ataxia Based on Gait Analysis Using Human Pose Estimation (2022), DOI 10.1109/IECBES54088.2022.10079396. <a href="https://data.mendeley.com/datasets/2vkk2r9tx3/1">Dataset (CC BY 4.0)</a>. Source-paper image reuse terms require confirmation before final distribution.</li><li>CARE-PD: cropped input-gait mesh example from the <a href="https://neurips2025.care-pd.ca/static/images/benchmark.png">official benchmark figure</a>. Adeli et al., NeurIPS 2025; dataset terms CC BY-NC 4.0. No identifiable RGB footage.</li><li>GMFCS: newly rendered skeleton from source-repository demo keypoints, input_000000000060_keypoints.json, <a href="https://github.com/stanfordnmbl/mobile-gaitlab">Kidziński et al.</a>. This is a source demo, not a confirmed benchmark test participant. The source trajectory terms differ from the Apache code license; no original demo RGB video is redistributed.</li><li>PARKINSONISM: cropped source-publication recording example from Deng et al., npj Parkinson's Disease 10, 122 (2024), DOI 10.1038/s41531-024-00742-x, CC BY 4.0. No ground-truth severity is inferred from appearance.</li><li>PATHOGAIT: rendered recorded joints from <a href="https://github.com/kooksung/pathological_gait_datasets">Jun et al. source repository</a>. No blanket data license was supplied; source permission for redistributed derived examples should be confirmed.</li></ul><p>Vector diagrams are newly drawn. Decorative traces are schematic, not patient measurements. Dataset provenance, release boundaries, and remaining permission checks are retained in the camera-ready preparation audit.</p></section></main></body></html>''')
